# Copia fija de las cinco líneas del tablero del equipo (no se importa del modelo: la migración no debe cambiar si él cambia).
LINEAS = ("BPO", "Custodia", "Digitalización", "Banca", "Estado")


def crear_lineas(apps, schema_editor):
    LineaServicio = apps.get_model("clientes", "LineaServicio")
    for nombre in LINEAS:
        LineaServicio.objects.get_or_create(nombre=nombre, defaults={"activa": True})


def borrar_lineas(apps, schema_editor):
    # Al revertir, esta operación corre después de quitar Contrato.linea_servicio (ver el orden de abajo): no hay
    # contratos que apunten a las líneas, así que se pueden borrar sin dejar referencias colgadas.
    apps.get_model("clientes", "LineaServicio").objects.filter(nombre__in=LINEAS).delete()


